// <diletta-avatar> — a INSTÂNCIA WEB de `design-system-avatar`.
//
// Não é uma porta do `DilettaAvatar`: é a outra instância da mesma spec
// (ADR-007 rev.3). A pintura NÃO está escrita aqui — ela vem de `pintura.g.js`,
// gerado da tabela que o Dart mede no render. Mudar a cor do avatar é mudar o
// Dart e regerar, nunca editar este arquivo.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-avatar';
const VARIANT = ['outlined', 'solid'];
const TYPE = ['initial', 'icon'];

// O glifo de pessoa, para `type="icon"`. Fica inline porque o pacote de ícones do
// pai é `.svg.vec`, um formato do `vector_graphics` que o navegador não lê — a
// fronteira está declarada em docs/O-QUE-A-WEB-USA.md.
const PESSOA =
  '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">' +
  '<circle cx="12" cy="8" r="3.5" stroke="currentColor" stroke-width="1.5"/>' +
  '<path d="M5 19c0-3.3 3.1-5.5 7-5.5s7 2.2 7 5.5" stroke="currentColor" ' +
  'stroke-width="1.5" stroke-linecap="round"/></svg>';

class DilettaAvatar extends HTMLElement {
  static observedAttributes = ['variant', 'type', 'nome', 'foto', 'letras'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  /// Até 2 letras, e elas saem do NOME — a spec pede iniciais, não uma string
  /// que quem chama já cortou. Cortar do lado de fora é como duas letras viram
  /// três em algum lugar.
  /// `letras` limita o teto para BAIXO, nunca para cima: a spec diz "até 2", e o
  /// atributo existe porque o `DilettaInputChip` pede UMA — *"sem foto, o avatar
  /// SHALL mostrar UMA inicial do rótulo"*. Um chip não é um caso especial de
  /// avatar: é a mesma peça com o teto mais baixo.
  get iniciais() {
    const teto = Math.min(2, Math.max(1, Number(this.getAttribute('letras')) || 2));
    const partes = (this.getAttribute('nome') || '').trim().split(/\s+/).filter(Boolean);
    if (!partes.length) return '';
    const letras = partes.length === 1 || teto === 1
        ? [partes[0][0]]
        : [partes[0][0], partes[partes.length - 1][0]];
    return letras.join('').toUpperCase();
  }

  render() {
    const variant = eixo(this, 'variant', VARIANT, 'outlined');
    const type = eixo(this, 'type', TYPE, 'initial');
    const papeis = papeisDe(SLUG, { Variant: variant });
    const foto = this.getAttribute('foto');

    // `role="img"` + `aria-label`: sem isto o leitor de tela lê duas letras
    // soltas, que não são o nome de ninguém.
    const nome = this.getAttribute('nome') || '';
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; --diletta-avatar-tamanho: 40px; }
        .casca {
          box-sizing: border-box;
          width: var(--diletta-avatar-tamanho);
          height: var(--diletta-avatar-tamanho);
          border-radius: 50%;
          /* Longhand, e NUNCA o atalho de borda: ele vem depois da pintura e
             reseta a cor que ela acabou de escrever. Medido no navegador em
             06/09 — a peça saía com borderColor rgba(0,0,0,0) e o teste, que lê
             o TEXTO do CSS, não via nada. Atalho depois de longhand apaga em
             silêncio. (Sem crase neste comentário: ele mora dentro de um
             template literal, e crase aqui fecha a string.) */
          border-width: 1px; border-style: solid; border-color: transparent;
          display: flex; align-items: center; justify-content: center;
          overflow: hidden;
          font: var(--cps-type-label-weight, 600) var(--cps-type-label-size, 14px)/1 system-ui, sans-serif;
          letter-spacing: .02em;
          ${estiloDa(papeis)}
        }
        img { width: 100%; height: 100%; object-fit: cover; }
        svg { width: 60%; height: 60%; }
      </style>
      <div class="casca" role="img" aria-label="${nome.replace(/"/g, '&quot;')}">
        ${foto ? `<img src="${foto}" alt="">` : type === 'icon' ? PESSOA : this.iniciais}
      </div>`;
  }
}

customElements.define('diletta-avatar', DilettaAvatar);
export { DilettaAvatar };
